-- 测试数据汇总：按 1~7 顺序合并，仅执行本文件即可（请确认库名/环境）。

-- ========== 1.插入10000名用户.sql ==========

-- id 1~10000；user_name/nick_name 为 TT0000~TT9999（与 id 对齐：TT = pad(id-1,4)）

-- ========== 2.前1000名用户互加好友.sql ==========

-- 用户 1~1000 两两互为好友（双向）：对任意 u≠v，同时存在 (user_id=u,friend_id=v) 与 (user_id=v,friend_id=u)。
-- 实现方式：对每个 u 写入其好友列表中全部 v≠u，共 1000×999=999000 行，已覆盖所有有序对，不是单向边。
-- 分 100 条 INSERT：每条连续 10 个 user_id，每人 999 条 VALUES。version 全局 1~999000。





































































































-- ========== 3.创建1000个十人群.sql ==========

-- 1000 个十人群：群名 十人群1 ~ 十人群1000；群主 owner_id = 群号 g。
-- 群 1~10 成员均为 user 1~10；群 11~20 成员均为 user 11~20；…；群 991~1000 成员均为 user 991~1000。
-- im_group_member 不指定 is_manager（走表默认值）。version 全局 1~10000。



ALTER TABLE im_group AUTO_INCREMENT = 1001;
-- 若 im_group_member 有自增冲突，可按当前 MAX(id)+1 调整：
-- ALTER TABLE im_group_member AUTO_INCREMENT = <max_id+1>;

-- ========== 4.创建100个百人群.sql ==========

-- 100 个百人群：群 id 1001~1100（假定十人群已占用 1~1000）。群名 百人群1 ~ 百人群100。
-- 群 1001~1010 成员均为 user 1~100；群 1011~1020 成员均为 user 101~200；…；群 1091~1100 成员均为 user 901~1000。
-- 每群 100 人；群主 owner_id 规则同前（群1001→user1，…群1010→user10，群1011→user101，…）。
-- 需已存在 im_user id 1~1000。不指定 is_manager；version 全局 1~10000。



ALTER TABLE im_group AUTO_INCREMENT = 1101;
-- 若 im_group_member 有自增冲突：ALTER TABLE im_group_member AUTO_INCREMENT = <max_id+1>;

-- ========== 5.创建10个千人群.sql ==========

-- 10 个千人群：群 id 1101~1110（假定十人群 1~1000、百人群 1001~1100 已占用）。群名 千人群1 ~ 千人群10。
-- 每个群成员均为 user 1~1000（前 1000 名用户同时在这 10 个群中）。每群 1000 人。
-- 群主：千人群k → owner_id = k（user k）。需已存在 im_user id 1~1000。不指定 is_manager；version 全局 1~10000。



ALTER TABLE im_group AUTO_INCREMENT = 1111;
-- 若 im_group_member 有自增冲突：ALTER TABLE im_group_member AUTO_INCREMENT = <max_id+1>;

-- ========== 6.创建10个万人群.sql ==========

-- 10 个万人群：群 id 1111~1120（假定十人群 1~1000、百人群 1001~1100、千人群 1101~1110 已占用）。群名 万人群1 ~ 万人群10。
-- 每个群成员均为 user 1~10000（前 10000 名用户同时在这 10 个群中）。每群 10000 人，共 100000 行 im_group_member。
-- 群主：万人群k → owner_id = k。需已存在 im_user id 1~10000。不指定 is_manager；version 全局 1~100000。



ALTER TABLE im_group AUTO_INCREMENT = 1121;
-- 若 im_group_member 有自增冲突：ALTER TABLE im_group_member AUTO_INCREMENT = <max_id+1>;
-- 单条 INSERT 行数多，必要时调大 max_allowed_packet。

-- ========== 7.初始化头像.sql ==========

-- 将用户表、好友表、群成员表头像统一为默认图（按需为 UPDATE 增加 WHERE，避免误更新生产数据）
SET NAMES utf8mb4;

UPDATE im_user
SET head_image = 'https://www.boxim.online/file/box-im/image/20260523/2057889495449083904.jpeg',
    head_image_thumb = 'https://www.boxim.online/file/box-im/image/20260523/2057889495449083904.jpeg';

UPDATE im_friend
SET friend_head_image = 'https://www.boxim.online/file/box-im/image/20260523/2057889495449083904.jpeg';

UPDATE im_group_member
SET head_image = 'https://www.boxim.online/file/box-im/image/20260523/2057889495449083904.jpeg';

